/* Extra state used only here (core S has no slots for these). */
S.lastRows=S.lastRows||{};S.badges=S.badges||{};S.calTypes=S.calTypes||null;S.refq=S.refq||"";

/* ---------- small helpers core.js lacks ---------- */
const IC=k=>(typeof ICON!=="undefined"&&ICON[k])||"";
var oldRefs=x=>[].concat(x?.oldRef||[]).filter(Boolean).join(", ");
const tagsTxt=x=>(x?.tags||[]).length?" · "+x.tags.map(t=>"#"+L("tag",t)).join(" "):"";
const hasQ=(col,x,q)=>!q||score(searchText(col,x),q)>0;
const fmtDT=iso=>iso?`${fmtD(iso.slice(0,10))} ${iso.slice(11,16)}`:"—";
const roleLabel=r=>item("role",r)?.label||r||"";
const gof=(k,f)=>esc(JSON.stringify({k,f})).replace(/'/g,"&#39;");
var pill=(txt,cls)=>`<span class="pill ${cls}">${esc(txt)}</span>`;
const OPEN_SH=["booked","in_transit","customs","arrived"];
const isLate=s=>!!s.eta&&!["delivered","cancelled","arrived","part_delivered"].includes(s.status)&&s.eta<today();
const shipPos=s=>[...new Set([...(s.lines||[]).map(l=>l.po),...(s.purchases||[])].filter(Boolean))];
const poGbp=p=>+p.totalGbpAtOrder||toGbp(poTotal(p),p.cur,p.date);
const payGbp=p=>p.gbpActual!=null&&p.gbpActual!==""?+p.gbpActual:p.gbp!=null&&p.gbp!==""?+p.gbp:toGbp(p.amount,p.cur,p.date);
const paySign=p=>p.direction==="in"?-1:1;
const payDept=p=>{const pa=party(p.party);return pa?(partyTypeDef(pa.type).dept||"other"):(p.dept||"other")};
const deptLabel=d=>{const it=items("partyType",{all:true}).find(i=>i.dept===d);return it?it.label:String(d).charAt(0).toUpperCase()+String(d).slice(1)};
const catMatch=(c,f)=>c===f||item("category",c)?.parent===f;
const catDuty=c=>{const it=item("category",c);if(!it)return null;const top=it.parent?item("category",it.parent):it;return top?.duty!=null?+top.duty:null};
const supOf=p=>(p?.suppliers||[]).slice().sort((a,b)=>(a.validFrom||a.lastDate||"")<(b.validFrom||b.lastDate||"")?1:-1)[0]||null;
const feePctFor=(p,partyCode)=>{const pa=party(partyCode);if(!pa?.viaAgent)return 0;return p?.isNew?FEES().chinaNew:(+pa.feePct||FEES().chinaOld)};
const SEV=[["p-mute","Info","var(--muted)"],["p-info","Soon","var(--info)"],["p-warn","Action","var(--warn)"],["p-bad","Urgent","var(--bad)"]];
/* core.attention() sorts with `b.sev-a.sev||(a.d<b.d)?-1:1` (precedence bug) — re-sort here: severity desc, then date asc */
function attn(){return S._att||(S._att=attention().slice().sort((a,b)=>(b.sev-a.sev)||((a.d||"")<(b.d||"")?-1:(a.d||"")>(b.d||"")?1:0)))}

/* CSS that head.html does not carry (list header, bars, event colours, link-buttons). Injected once. */
const VIEW_CSS=`.lhead{display:grid;grid-template-columns:118px minmax(0,1fr) 120px 120px 118px;gap:12px;padding:6px 14px;border-bottom:1px solid var(--line);font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em}.lhead button{border:0;background:transparent;color:inherit;font:inherit;padding:0;text-align:left;text-transform:inherit;letter-spacing:inherit}.lhead button.on{color:var(--fg)}.lhead .r{text-align:right}
.row .amt b{display:block;font-family:var(--f-data);font-weight:600}.row .ck{margin-right:6px;vertical-align:middle}.row .stc .pill{margin-right:4px}
.lnk{border:0;background:transparent;padding:0;color:inherit;font:inherit;text-align:left;font-weight:600;cursor:pointer}.lnk:hover{color:var(--accent)}
.hdr{display:flex;justify-content:space-between;align-items:flex-start;gap:8px;flex-wrap:wrap}.hdr .acts{display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.bars{display:flex;gap:6px;align-items:flex-end;padding:14px;overflow-x:auto}.bars .b{flex:1;min-width:38px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:3px;font-size:10px;color:var(--muted)}.bars .b i{display:block;width:100%;background:var(--accent);border-radius:3px 3px 0 0;min-height:2px}.bars .b b{font:600 10px var(--f-data);color:var(--fg);white-space:nowrap}
.cal .ev{color:var(--fg)}.ev-due{background:var(--warn-bg)}.ev-eta{background:var(--info-bg)}.ev-ship{background:var(--soft)}.ev-ready{background:var(--accent-soft)}.ev-insp{background:var(--soft)}.ev-paid{background:var(--ok-bg)}.ev-reorder{background:var(--bad-bg)}.ev-slot{background:var(--info-bg)}.ev.done{opacity:.55;text-decoration:line-through}
.cal .day[data-day]{cursor:pointer}.cal .day[data-day]:hover{border-color:var(--accent)}
.tile small{display:block;color:var(--muted);font-size:11px;margin-top:2px}
details.how{display:inline-block;font-size:11.5px;color:var(--muted);margin-left:4px;vertical-align:top;max-width:100%}details.how>summary{cursor:pointer;list-style:none;color:var(--accent);font-weight:600;display:inline}details.how>summary::-webkit-details-marker{display:none}details.how[open]{display:block;margin:4px 0 2px}details.how .howb{display:block;margin-top:4px;padding:8px 10px;border-radius:8px;background:var(--soft);color:var(--fg);font-size:12px;line-height:1.5;text-align:left;font-weight:400;white-space:normal;overflow-wrap:anywhere}td details.how .howb{min-width:220px}
.tool{padding:14px;display:flex;flex-direction:column;gap:10px}.att .btn{flex:none}.chip.arch{opacity:.5}
@media (max-width:860px){.lhead{display:none}.hdr .acts .btn{flex:1;text-align:center}.att{flex-wrap:wrap}.att .t{flex-basis:calc(100% - 20px)}}`;
function ensureCss(){if($("#vcss"))return;const s=document.createElement("style");s.id="vcss";s.textContent=VIEW_CSS;document.head.appendChild(s)}

/* ---------- render ---------- */
const vMissing=n=>v=>{v.innerHTML=`<div class="card empty">${esc(n)} is not available in this build.</div>`};
const VIEWS=()=>({home:vHome,purchases:vPurchases,shipments:vShipments,payments:vPayments,stock:vStock,products:vProducts,parties:vParties,calendar:vCalendar,tools:vTools,refs:vRefs,reports:vReports,import:typeof vImport==="function"?vImport:vMissing("Import"),attention:vAttention,log:vLog,trash:vTrash,setup:typeof vSetup==="function"?vSetup:vMissing("Setup"),planner:typeof vPlanner==="function"?vPlanner:vMissing("Planner"),more:vMore,doc:vHome});
function render(){ensureCss();S._att=null;const v=$("#view");if(!v)return;const ae=document.activeElement;const inside=s=>!!(ae&&ae.closest&&ae.closest(s));
 const hold=S.holdRender||inside("#setupbody")||inside("#view [data-tool]")||(inside(".drawer")&&!!S.drawer?.form);
 if(!hold){try{nav()}catch(e){console.error(e)}
  if(!S.ready)v.innerHTML=`<div class="card empty">${S.err?esc(S.err):"Loading your NEXUS data…"}</div>`;
  else{const fn=VIEWS()[S.view.k]||vHome;try{fn(v)}catch(e){console.error(e);v.innerHTML=`<div class="card empty">This page hit an error: ${esc(e.message||e)}<br><br><button class="btn" data-view="home">Go home</button></div>`}foldFilters(v)}}
 renderLayer();
 const en=(id,on)=>{const b=$(id);if(b)b.disabled=!on};en("#backb",S.hi>0);en("#fwdb",S.hi<S.hist.length-1);en("#undob",S.undo.length>0);en("#redob",S.redo.length>0);
 const bell=$("#bell");if(bell){const need=attn().some(a=>a.sev>=2);let d=bell.querySelector(".dot");if(need&&!d){d=document.createElement("span");d.className="dot";bell.appendChild(d)}else if(!need&&d)d.remove()}}
function foldFilters(v){const fb=v.querySelector('.filters[role=group]');if(!fb||S.view.k==="setup")return;const f=F();const n=Object.keys(f).filter(k=>f[k]!==""&&f[k]!=null&&k!=="sort").length;const open=!!(S.fopen||{})[S.view.k];fb.classList.add("fold");fb.classList.toggle("open",open);const b=document.createElement("button");b.type="button";b.className="chipb ftoggle";b.dataset.act="ffold";b.setAttribute("aria-expanded",String(open));b.textContent=(open?"Hide filters":"Filters")+(n?` (${n})`:"");fb.parentNode.insertBefore(b,fb)}
function renderLayer(){const layer=$("#layer");if(!layer)return;const d=S.drawer;if(!d?.form){const b=$("#dirtybar");if(b)b.hidden=true}const key=d?(d.form?"form:"+d.form+":"+(d._k||(d._k=nid())):"doc:"+d.col+":"+d.id):"";const same=layer.dataset.key===key;
 if(!(key.startsWith("form:")&&same)){/* an open form keeps its live DOM (typed values); doc drawers always refresh */
  const st=same?($(".drawer .db")?.scrollTop||0):0;layer.innerHTML=d?(d.form?formShell(d.form):(typeof renderDrawer==="function"?renderDrawer():"")):"";layer.dataset.key=key;const db=$(".drawer .db");if(db&&st)db.scrollTop=st}
 [$(".app"),$("#tabbar")].forEach(el=>{if(el)el.toggleAttribute("inert",!!d)});$("#toast")?.classList.toggle("top",!!d)}

/* ---------- nav: rail (desktop) + tab bar (phone), badges = items needing action ---------- */
function nav(){const b={purchases:0,shipments:0,payments:0,stock:0};attn().forEach(a=>{if((a.sev||0)<1)return;const k=a.col==="products"?"stock":a.col;if(k in b)b[k]++});S.badges=b;const k=S.view.k;
 const btn=(v,l,ic)=>`<button class="nav ${k===v?"on":""}" data-view="${v}" ${k===v?'aria-current="page"':""}>${IC(ic)}<span>${esc(l)}</span>${b[v]?`<span class="cnt" title="Needs action">${b[v]}</span>`:""}</button>`;
 const more=MORE.filter(([v])=>(v!=="setup"||can("setup"))&&(v!=="import"||can("create")));
 const rail=$("#rail");if(rail)rail.innerHTML=`<div class="brand"><img src="assets/icon-192.png" alt=""><div><b><i>MY</i> TOOL</b><small>VARTLEAVES · SOURCING</small></div></div>${MAIN.map(([v,l])=>btn(v,l,v)).join("")}<h6>More</h6>${more.map(([v,l,i])=>btn(v,l,i)).join("")}
  <div style="margin-top:auto;padding:10px" class="status"><button type="button" id="mt_sync" data-act="syncnow" data-kind="${esc(window.MYTOOL?.st?.k||"ok")}" title="Tap to save / get latest now">${esc(window.MYTOOL?.st?.t||(S.ready?"● Live":"Connecting…"))}</button><div class="who">${window.MYTOOL?.me?.picture?`<img src="${esc(MYTOOL.me.picture)}" alt="">`:""}<span>${esc(user?.name||"")}<br><small>${esc(roleLabel(S.role))}</small></span></div>${window.MYTOOL&&!MYTOOL.demo?`<button type="button" class="btn sm" data-act="signout" style="margin-top:6px">Sign out</button>`:""}${S.realRole==="owner"?`<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px"><button type="button" class="btn sm" data-act="mtbackup" title="Download all data as a file">⬇ Backup</button><label class="btn sm" title="Replace all data with a MY TOOL starting / backup file">⬆ Load data file<input type="file" class="mt_restore" accept=".json,application/json" hidden></label></div>`:""}${roleSwitch()}</div>`;
 const tabs=[...MAIN.filter(([v])=>v!=="payments"),["more","More"]];const isMain=tabs.some(([v])=>v===k);
 const tb=$("#tabbar");if(tb)tb.innerHTML=tabs.map(([v,l])=>{const on=v==="more"?!isMain:k===v;return`<button class="${on?"on":""}" data-view="${v}" ${on?'aria-current="page"':""}>${IC(v)}<span>${esc(l)}${b[v]?" · "+b[v]:""}</span></button>`}).join("")}
function roleSwitch(){if(!(S.role==="owner"||can("setup")))return"";const roles=[...new Set([...Object.keys(SET().roles||{}),...items("role").map(r=>r.id)])];return`<div style="margin-top:8px">View as</div><div class="roles" style="margin-top:4px;flex-wrap:wrap">${roles.map(r=>`<button type="button" class="rb ${S.role===r?"on":""}" data-role="${esc(r)}" aria-pressed="${S.role===r}">${esc(roleLabel(r))}</button>`).join("")}</div>`}

/* ---------- generic page helpers ---------- */
function crumb(parts){return`<nav class="crumb" aria-label="Breadcrumb">${parts.map((p,i)=>i<parts.length-1?`<button type="button" data-crumb="${esc(p[1]||"home")}">${esc(p[0])}</button><span aria-hidden="true">›</span>`:`<span aria-current="page">${esc(p[0])}</span>`).join("")}</nav>`}
function sel(page,key,labelTxt,opts,o={}){const cur=F(page)[key];return`<select data-f="${esc(key)}" aria-label="${esc(labelTxt)}" ${o.disabled?"disabled":""} ${o.title?`title="${esc(o.title)}"`:""}><option value="">${esc(labelTxt)}: all</option>${(opts||[]).map(x=>{const[val,lab]=Array.isArray(x)?x:[x,x];return`<option value="${esc(val)}" ${String(cur??"")===String(val)?"selected":""}>${esc(lab)}</option>`}).join("")}</select>`}
function tog(page,key,labelTxt){const on=!!F(page)[key];return`<button type="button" class="chipb ${on?"on":""}" data-f-toggle="${esc(key)}" aria-pressed="${on}">${esc(labelTxt)}</button>`}
const amountInputs=page=>`<input data-f="min" type="number" inputmode="decimal" placeholder="£ from" aria-label="Minimum £" value="${esc(F(page).min||"")}" style="width:96px"><input data-f="max" type="number" inputmode="decimal" placeholder="£ to" aria-label="Maximum £" value="${esc(F(page).max||"")}" style="width:96px">`;
const DATE_PRESETS=[["today","Today"],["7d","Last 7 days"],["30d","Last 30 days"],["90d","Last 90 days"],["month","This month"],["lastm","Last month"],["quarter","This quarter"],["year","This year"],["custom","Custom…"]];
function dateRange(preset,f={}){const T=today();switch(preset){case"today":return[T,T];case"7d":return[addDays(T,-6),T];case"30d":return[addDays(T,-29),T];case"90d":return[addDays(T,-89),T];case"month":return[addMonths(T,0),addDays(addMonths(T,1),-1)];case"lastm":return[addMonths(T,-1),addDays(addMonths(T,0),-1)];case"quarter":{const[y,m]=T.split("-").map(Number);const s=`${y}-${String(Math.floor((m-1)/3)*3+1).padStart(2,"0")}-01`;return[s,addDays(addMonths(s,3),-1)]}case"year":return[T.slice(0,4)+"-01-01",T.slice(0,4)+"-12-31"];case"custom":return[f.from||"",f.to||""];default:return null}}
function inDate(iso,f){if(typeof f==="string")f={date:f};const p=f?.date;if(!p)return true;const r=dateRange(p,f);if(!r)return true;if(!iso)return false;iso=String(iso).slice(0,10);return(!r[0]||iso>=r[0])&&(!r[1]||iso<=r[1])}
const datePresetMatch=(iso,preset,f)=>inDate(iso,{...(f||{}),date:preset});
const inPeriod=(iso,f)=>f.date?inDate(iso,f):(!f.year||String(iso||"").startsWith(f.year));
function normFObj(f){const o={};Object.keys(f||{}).sort().forEach(k=>{const v=f[k];if(v==null||v===""||v===false)return;o[k]=v});return o}
const normF=f=>JSON.stringify(normFObj(f));
const activeCount=page=>Object.keys(normFObj(F(page))).filter(k=>k!=="sort").length;
function sortRows(rows,sort,get,def){const[k,dir]=String(sort||def||"date_desc").split("_");const g=get[k]||get[String(def||"").split("_")[0]]||(()=>0);const m=dir==="asc"?1:-1;return rows.slice().sort((a,b)=>{const x=g(a),y=g(b);if(x==null&&y==null)return 0;if(x==null)return 1;if(y==null)return-1;return(x<y?-1:x>y?1:0)*m})}
function filterBar(page,controls,o={}){const f=F(page);const dateOn=!!f.date;
 const q=o.noQ?"":`<input data-f="q" type="search" placeholder="Search this list" aria-label="Search this list" value="${esc(f.q||"")}" style="min-width:150px;flex:1">`;
 const yr=o.years&&o.years.length?sel(page,"year","Year",o.years,{disabled:dateOn,title:dateOn?"Clear the Date filter to use Year":""}):"";
 const dt=o.noDate?"":sel(page,"date","Date",DATE_PRESETS)+(f.date==="custom"?`<input data-f="from" type="date" value="${esc(f.from||"")}" aria-label="From date"><input data-f="to" type="date" value="${esc(f.to||"")}" aria-label="To date">`:"");
 const srt=o.sorts?`<select data-f="sort" aria-label="Sort">${o.sorts.map(([v,l])=>`<option value="${v}" ${(f.sort||o.def)===v?"selected":""}>Sort: ${esc(l)}</option>`).join("")}</select>`:"";
 const hidden=(o.hidden||[]).filter(([k])=>f[k]).map(([k,l])=>tog(page,k,l+" ✕")).join("");const n=activeCount(page);
 return`<div class="filters" role="group" aria-label="Filters">${q}${controls||""}${yr}${dt}${srt}${hidden}${n?`<button type="button" class="chipb" data-act="clearf">Clear all (${n})</button>`:""}</div>`}
function savedViewsBar(page){const f=F(page);const cur=normF(f);const views=live(D.views).filter(v=>v.page===page).sort((a,b)=>(a.name||"").localeCompare(b.name||""));const active=views.find(v=>normF(v.f||{})===cur);const has=activeCount(page)>0||!!f.sort;
 return`<div class="filters" aria-label="Saved views">${views.map(v=>`<button type="button" class="chipb ${v===active?"on":""}" data-sv="${esc(v.id)}" aria-pressed="${v===active}">${esc(v.name)}</button>`).join("")}${active&&can("edit")&&S.renView===active.id?`<span class="inl" style="margin:0"><input id="svren_${esc(active.id)}" value="${esc(active.name)}" aria-label="New name for this view" style="width:150px"><button type="button" class="chipb" data-act="renviewok" data-id="${esc(active.id)}">Save name</button><button type="button" class="chipb" data-act="renview" data-id="${esc(active.id)}">Cancel</button></span>`:""}${active&&can("edit")&&S.renView!==active.id?`<button type="button" class="chipb" data-act="renview" data-id="${esc(active.id)}" aria-label="Rename view">✎</button><button type="button" class="chipb" data-act="delview" data-id="${esc(active.id)}" aria-label="Delete view">🗑</button>`:""}${has&&!active?`<span class="inl" style="margin:0"><input id="svname" placeholder="Name this view" aria-label="View name" style="width:150px"><button type="button" class="chipb" data-act="saveview" data-page="${esc(page)}">＋ Save view</button></span>`:""}</div>`}
function countText(page,rows,total){const lim=S.limit[page]||60;const shown=Math.min(lim,rows.length);return`${shown} of ${rows.length}${total!=null&&total!==rows.length?` matching · ${total} total`:""}`}
function listFooter(page,rows,total){const lim=S.limit[page]||60;const rest=rows.length-Math.min(lim,rows.length);
 return`<div class="more" style="display:flex;gap:8px;justify-content:center;align-items:center;flex-wrap:wrap"><span class="status" id="listcount">${countText(page,rows,total)}</span>${rest>0?`<button type="button" class="btn sm" data-act="more">Show more (${Math.min(rest,60)})</button><button type="button" class="btn sm" data-act="all">Show all (${rest})</button>`:""}${can("export")&&rows.length?`<button type="button" class="btn sm" data-act="exportview" data-page="${esc(page)}">⇩ Export this view</button><button type="button" class="btn sm" data-act="exportviewcsv" data-page="${esc(page)}">⇩ CSV</button>`:""}</div>`}
/* S.sel[page] is a plain object {id:true} */
const selIds=page=>Object.keys(S.sel[page]||{}).filter(k=>S.sel[page][k]);
function rowCk(page,id){if(!(LIST[page]?.bulk||[]).length)return"";const on=!!(S.sel[page]||{})[id];return`<input class="ck" type="checkbox" data-sel="${esc(id)}" ${on?"checked":""} aria-label="Select ${esc(id)}">`}
function bulkBar(page){const ops=LIST[page]?.bulk||[];const n=selIds(page).length;if(!n||!ops.length)return`<div id="bulkbar"></div>`;const lab={archive:"Archive",close:"Close",arrived:"Mark arrived",tag:"Tag…",export:"Export",trash:"Trash"};
 return`<div id="bulkbar"><div class="bulk"><b>${n} selected</b>${ops.includes("tag")&&can("edit")?`<select id="bulktag" aria-label="Tag to add"><option value="">Tag…</option>${optsHtml(items("tag").map(t=>[t.id,t.label]),"")}</select>`:""}${ops.filter(op=>op==="trash"?can("deleteAny"):op==="export"?can("export"):can("edit")).map(op=>`<button type="button" class="btn sm ${op==="trash"?"danger":""}" data-act="bulk" data-op="${op}">${op==="tag"?"Add tag":lab[op]||op}</button>`).join("")}<button type="button" class="btn sm" data-act="bulk" data-op="clear">Clear selection</button></div></div>`}
function lhead(page,head,def){if(!head)return"";const s=F(page).sort||def||"";const[sk,sd]=s.split("_");return`<div class="lhead">${head.map(([k,l,r])=>k?`<span class="${r?"r":""}"><button type="button" data-sort="${k}" class="${sk===k?"on":""}">${esc(l)}${sk===k?(sd==="asc"?" ↑":" ↓"):""}</button></span>`:`<span class="${r?"r":""}">${esc(l)}</span>`).join("")}</div>`}
function listBody(page){const spec=LIST[page];const rows=spec.rows();S.lastRows[page]=rows;const lim=S.limit[page]||60;const shown=rows.slice(0,lim);return{rows,html:shown.length?shown.map(spec.row).join(""):`<div class="empty">${esc(spec.empty||"Nothing matches these filters.")}${activeCount(page)?' <button type="button" class="btn sm" data-act="clearf">Clear filters</button>':""}</div>`}}
function renderList(){const page=S.view.k;const spec=LIST[page];const b=$("#listbody");if(!spec||!b){render();return}const{rows,html}=listBody(page);const total=spec.total?spec.total():undefined;b.innerHTML=html;const c=$("#listcount");if(c)c.textContent=countText(page,rows,total);const f=$("#listfoot");if(f)f.innerHTML=listFooter(page,rows,total);const bb=$("#bulkbar");if(bb)bb.outerHTML=bulkBar(page)}
function listPage(v,page,o){const spec=LIST[page];const{rows,html}=listBody(page);const total=spec.total?spec.total():undefined;const sub=typeof o.sub==="function"?o.sub(rows):o.sub;
 v.innerHTML=`${crumb([["Home","home"],[o.title]])}<div class="hdr"><div><h1>${esc(o.title)}</h1><p class="sub">${sub||""}</p></div><div class="acts">${o.acts||""}${o.newKey&&can("create")?`<button class="btn pri" data-act="new" data-k="${o.newKey}">+ ${esc(o.newLabel||o.title)}</button>`:""}</div></div>
 ${filterBar(page,o.controls,{years:o.years,sorts:o.sorts,def:o.def,hidden:o.hidden,noDate:o.noDate})}${savedViewsBar(page)}
 <div class="card list">${bulkBar(page)}${lhead(page,o.head,o.def)}<div id="listbody">${html}</div><div id="listfoot">${listFooter(page,rows,total)}</div></div>`}

/* ---------- option builders: Setup list ∪ distinct data values, unmapped flagged ---------- */
function listUnion(listKey,vals,o={}){const its=listDef(listKey).items;const out=[];const seen=new Set();(o.two?listOpts(listKey):its.filter(i=>!i.archived).map(i=>[i.id,i.label])).forEach(([id,l])=>{seen.add(id);out.push([id,l])});
 [...new Set((vals||[]).filter(v=>v!=null&&v!==""))].forEach(v=>{if(seen.has(v))return;seen.add(v);const it=its.find(i=>i.id===v);out.push([v,it?L(listKey,v)+" (archived)":String(v)+" (unmapped)"])});return out}
function partyOpts(types,vals){const ps=live(D.parties).filter(p=>p.status!=="archived"&&(!types||types.includes(p.type))).sort((a,b)=>(a.name||"").localeCompare(b.name||""));const out=ps.map(p=>[p.code,`${p.name||p.code}${p.company&&p.company!==p.name?" · "+p.company:""} · ${p.code}`]);const seen=new Set(out.map(x=>x[0]));
 [...new Set((vals||[]).filter(Boolean))].forEach(c=>{if(seen.has(c))return;seen.add(c);const p=party(c);out.push([c,p?`${p.name} · ${c} (archived)`:c+" (unmapped)"])});return out}
function setOpts(arr,vals,lab){const out=(arr||[]).filter(x=>!x.archived).map(x=>[x.id,lab?lab(x):x.name]);const seen=new Set(out.map(x=>x[0]));[...new Set((vals||[]).filter(Boolean))].forEach(v=>{if(seen.has(v))return;seen.add(v);const x=(arr||[]).find(y=>y.id===v);out.push([v,x?(lab?lab(x):x.name)+" (archived)":String(v)+" (unmapped)"])});return out}
const compOpts=vals=>setOpts(SET().companies,vals,c=>c.name+(c.tag?" ("+c.tag+")":""));
const bankOpts=vals=>setOpts(SET().banks,vals);
const locOpts=vals=>{const out=locs().map(l=>[l.id,locName(l.id)]);const seen=new Set(out.map(x=>x[0]));[...new Set((vals||[]).filter(Boolean))].forEach(v=>{if(seen.has(v))return;seen.add(v);out.push([v,loc(v)?locName(v)+" (archived)":String(v)+" (unmapped)"])});return out};
const yearsOf=(...arrs)=>[...new Set(arrs.flat().map(x=>String(x.date||x.dispatch||"").slice(0,4)).filter(y=>/^\d{4}$/.test(y)))].sort().reverse();
const tagOpts=()=>items("tag").map(t=>[t.id,t.label]);

/* ---------- pills ---------- */
const poPill=st=>pill(L("poStatus",st)||"—",["closed","received"].includes(st)?"p-ok":["cancelled","draft"].includes(st)?"p-mute":st==="hold"?"p-bad":"p-info");
const shPill=s=>pill(L("shipStatus",s.status)||"—",s.status==="delivered"?"p-ok":s.status==="cancelled"?"p-mute":["arrived","part_delivered"].includes(s.status)?"p-warn":"p-info");
const payPill=l=>pill(l,l==="Paid"||l==="Paid (no PI)"?"p-ok":l==="Unpaid"?"p-bad":l==="No PI"?"p-mute":"p-warn");

/* ---------- list registry (rows() = filtered+sorted, row(x) = html) ---------- */
const LIST={
 purchases:{rows:purchaseRows,row:poRow,bulk:["close","tag","export","trash"],total:()=>live(D.purchases).length,empty:"No purchases match these filters."},
 shipments:{rows:shipmentRows,row:shRow,bulk:["arrived","tag","export","trash"],total:()=>live(D.shipments).length,empty:"No shipments match these filters."},
 payments:{rows:paymentRows,row:payRow,bulk:["tag","export","trash"],total:()=>live(D.payments).length,empty:"No payments match these filters."},
 stock:{rows:stockRows,row:stockRow,bulk:[],total:()=>stockProducts().length,empty:"No products match these filters."},
 products:{rows:productRows,row:productRow,bulk:["archive","tag","export"],total:()=>D.products.filter(p=>!p.mergedInto).length,empty:"No products match these filters."},
 parties:{rows:partyRows,row:partyRow,bulk:["archive","export"],total:()=>live(D.parties).length,empty:"No parties match these filters."},
 attention:{rows:attentionRows,row:attRow,bulk:[],total:()=>attn().length,empty:"Nothing here — all clear."},
 log:{rows:logList,row:e=>logRows([e]),bulk:[],total:()=>D.log.length,empty:"No activity yet."}};

/* ===================== Purchases ===================== */
function purchaseRows(){const f=F("purchases");const docTypes=items("docType").filter(d=>(d.for||[]).includes("purchases"));
 const rows=live(D.purchases).filter(p=>{if(f.party&&p.party!==f.party)return false;if(f.status&&p.status!==f.status)return false;if(f.kind&&(p.kind||"china")!==f.kind)return false;if(f.account&&p.account!==f.account)return false;if(f.cur&&p.cur!==f.cur)return false;
  if(!inPeriod(p.date,f))return false;if(f.sku&&!(p.lines||[]).some(l=>l.sku===f.sku))return false;if(f.tag&&!(p.tags||[]).includes(f.tag))return false;
  if(f.hold&&!p.hold)return false;if(f.nosku&&!(p.lines||[]).some(l=>!l.sku))return false;if(f.legacy&&!Object.keys(p.legacy||{}).length)return false;if(f.nodocs&&!docTypes.some(d=>!p.docs?.[d.id]))return false;
  if(f.min||f.max){const g=poGbp(p);if(f.min&&g<+f.min)return false;if(f.max&&g>+f.max)return false}
  if(f.owing){if(p.status==="cancelled")return false;const st=poState(p);if(!(st.total>0&&st.outstandingCur>0.5))return false}
  return hasQ("purchases",p,f.q)});
 return sortRows(rows,f.sort,{date:p=>p.date||"",amount:p=>poGbp(p),owing:p=>poState(p).outstandingGbp},"date_desc")}
function poRow(p){const st=poState(p);const pct=Math.round(Math.min(100,st.pct*100));
 return`<div class="row" role="button" tabindex="0" data-open="purchases" data-id="${esc(p.no)}"><span class="ref">${rowCk("purchases",p.no)}${esc(p.no)}<small>${esc(oldRefs(p))}</small></span>
 <span class="d"><b>${esc(poDesc(p)||"—")}</b><span>${esc(pname(p.party))} · ${fmtD(p.date)} · ${esc(company(p.account)?.tag||cname(p.account))}${p.kind&&p.kind!=="china"?" · "+esc(L("purchaseKind",p.kind)):""}${p.piNo||p.yourRef?" · PI "+esc(p.yourRef||p.piNo):""}${tagsTxt(p)}</span></span>
 <span class="amt num"><b>${st.total?fmt(st.total,p.cur):"—"}</b><small>${st.total?gbp(poGbp(p)):"no PI total"}</small>${(()=>{const sp=(p.extras||[]).some(isOther)||(p.lines||[]).some(isOther)?poSplit(p):null;return(sp&&sp.othersSum?`<small class="pill p-warn mixb" title="${esc(`On this invoice: this order ${fmt(sp.thisOrder,p.cur)} + for something else ${fmt(sp.othersSum,p.cur)} (${sp.others.map(o=>ownerText(o)).join("; ")})`)}">＋ other ${esc(fmt(sp.othersSum,p.cur))}</small>`:"")+(st.via.length?`<small class="pill p-info mixb" title="${esc(st.via.map(v=>`${fmt(v.amt,v.cur)} billed on ${v.from}`).join("; "))}">via ${esc([...new Set(st.via.map(v=>v.from))].join(", "))}</small>`:"")})()}</span>
 <span class="amt num hm">${st.total?`<b>${pct}% paid</b><div class="bar" role="progressbar" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><i style="width:${pct}%"></i></div><small>${st.outstandingCur>0.5?fmt(st.outstandingCur,p.cur)+" to pay":st.owedToUs>0.5?"supplier owes "+fmt(st.owedToUs,p.cur):st.writtenOff?"rest written off":"settled"}</small>`:"<b>—</b>"}</span>
 <span class="stc">${poPill(p.status)}${payPill(st.payLabel)}${p.hold?pill("Hold","p-bad"):""}</span></div>`}
function vPurchases(v){const all=live(D.purchases);
 const controls=sel("purchases","party","Supplier",partyOpts(["supplier"],all.map(p=>p.party)))+sel("purchases","status","Status",listUnion("poStatus",all.map(p=>p.status)))+sel("purchases","kind","Kind",listUnion("purchaseKind",all.map(p=>p.kind)))+sel("purchases","account","Company",compOpts(all.map(p=>p.account)))+sel("purchases","cur","Currency",listUnion("currency",all.map(p=>p.cur)))+sel("purchases","sku","Product",D.products.filter(p=>!p.mergedInto).map(p=>[p.sku,`${p.name} · ${p.sku}`]))+sel("purchases","tag","Tag",tagOpts())+amountInputs("purchases")+tog("purchases","owing","Still to pay")+tog("purchases","hold","On hold")+tog("purchases","nodocs","Missing docs");
 listPage(v,"purchases",{title:"Purchases",newKey:"purchase",newLabel:"Purchase",controls,years:yearsOf(all),sub:rows=>`${rows.length} orders · ${gbp(rows.reduce((s,p)=>s+(p.status==="cancelled"?0:poState(p).outstandingGbp),0))} still to pay in this view`,
  sorts:[["date_desc","Newest"],["date_asc","Oldest"],["amount_desc","Amount high→low"],["amount_asc","Amount low→high"],["owing_desc","Most outstanding"]],def:"date_desc",hidden:[["nosku","Lines without product"],["legacy","Unmapped legacy values"]],head:[["","Ref"],["date","Order"],["amount","Total",1],["owing","Paid",1],["","Status"]]})}

/* ===================== Shipments ===================== */
function shipmentRows(){const f=F("shipments");const rows=live(D.shipments).filter(s=>{if(f.party&&s.party!==f.party)return false;if(f.status&&s.status!==f.status)return false;if(f.mode&&s.mode!==f.mode)return false;if(f.po&&!shipPos(s).includes(f.po))return false;if(f.open&&!OPEN_SH.includes(s.status))return false;if(f.late&&!isLate(s))return false;
 if(f.loc&&!(s.deliverTo===f.loc||(s.destinations||[]).some(d=>d.loc===f.loc)))return false;if(!inPeriod(s.dispatch||s.date,f))return false;if(f.tag&&!(s.tags||[]).includes(f.tag))return false;
 if(f.noorders&&(s.historic||s.status==="cancelled"||shipPos(s).length))return false;if(f.legacy&&!Object.keys(s.legacy||{}).length)return false;return hasQ("shipments",s,f.q)});
 return sortRows(rows,f.sort,{eta:s=>s.eta||null,dispatch:s=>s.dispatch||s.date||"",cost:s=>shipCostGbp(s)},"dispatch_desc")}
function shRow(s){const pos=shipPos(s);const w=shipWeights(s);const ctn=+s.ctn||w.ctn,kg=+s.kg||w.kg;const late=isLate(s);const paid=paysFor(s.no).reduce((a,p)=>a+allocGbp(p,s.no),0);
 return`<div class="row" role="button" tabindex="0" data-open="shipments" data-id="${esc(s.no)}"><span class="ref">${rowCk("shipments",s.no)}${esc(s.no)}<small>${esc(oldRefs(s))}</small></span>
 <span class="d"><b>${esc(pname(s.party))} · ${esc(L("mode",s.mode)||"—")}${pos.length?" · "+esc(pos.join(", ")):s.goods?" · "+esc(String(s.goods).slice(0,70)):""}</b><span>${ctn?ctn+" ctn":""}${kg?" · "+num(kg,1)+" kg":""}${s.dispatch||s.date?" · sent "+fmtD(s.dispatch||s.date):""}${s.eta?" · ETA "+fmtD(s.eta):""}${s.deliverTo?" → "+esc(locName(s.deliverTo)):""}${tagsTxt(s)}</span></span>
 <span class="amt num"><b>${+s.cost?fmt(s.cost,s.costCur||"USD"):"—"}</b><small>${+s.cost?gbp(shipCostGbp(s)):""}</small></span>
 <span class="amt num hm"><b>${s.eta?fmtD(s.eta):"—"}</b><small>${late?`late ${diffDays(s.eta,today())} d`:paid?"paid "+gbp(paid):"ETA"}</small></span>
 <span class="stc">${shPill(s)}${late?pill("Late","p-bad"):""}${!s.historic&&!pos.length&&s.status!=="cancelled"?pill("No orders","p-mute"):""}</span></div>`}
function vShipments(v){const all=live(D.shipments);const refd=new Set(all.flatMap(shipPos));const poOpts=live(D.purchases).filter(p=>!["closed","cancelled"].includes(p.status)||refd.has(p.no)).sort((a,b)=>a.no<b.no?1:-1).map(p=>[p.no,`${p.no} · ${pname(p.party)}`]);
 const controls=sel("shipments","party","Forwarder",partyOpts(["forwarder"],all.map(s=>s.party)))+sel("shipments","status","Status",listUnion("shipStatus",all.map(s=>s.status)))+sel("shipments","mode","Service",listUnion("mode",all.map(s=>s.mode)))+sel("shipments","po","Order",poOpts)+sel("shipments","loc","Destination",locOpts(all.flatMap(s=>[s.deliverTo,...(s.destinations||[]).map(d=>d.loc)])))+sel("shipments","tag","Tag",tagOpts())+tog("shipments","open","On the way")+tog("shipments","late","Late");
 listPage(v,"shipments",{title:"Shipments",newKey:"shipment",newLabel:"Shipment",controls,years:yearsOf(all),sub:rows=>`${rows.length} shipments · ${rows.filter(s=>OPEN_SH.includes(s.status)).length} on the way · freight cost flows into landed cost per pack`,
  sorts:[["dispatch_desc","Newest"],["dispatch_asc","Oldest"],["eta_asc","ETA soonest"],["eta_desc","ETA latest"],["cost_desc","Cost high→low"]],def:"dispatch_desc",hidden:[["noorders","Without orders linked"],["legacy","Unmapped legacy values"]],head:[["","Ref"],["dispatch","Shipment"],["cost","Cost",1],["eta","ETA",1],["","Status"]]})}

/* ===================== Payments ===================== */
function paymentRows(){const f=F("payments");const rows=live(D.payments).filter(p=>{if(f.party&&p.party!==f.party)return false;if(f.dept&&payDept(p)!==f.dept)return false;if(f.type&&p.type!==f.type)return false;if(f.status&&p.status!==f.status)return false;if(f.bank&&p.bank!==f.bank)return false;if(f.platform&&p.platform!==f.platform)return false;if(f.paidBy&&(p.paidBy||"company")!==f.paidBy)return false;if(f.company&&p.company!==f.company)return false;if(f.cur&&p.cur!==f.cur)return false;
 if(!inPeriod(p.date,f))return false;const g=payGbp(p);if(f.min&&g<+f.min)return false;if(f.max&&g>+f.max)return false;if(f.check&&payCheck(p)[0]!==f.check)return false;if(f.tag&&!(p.tags||[]).includes(f.tag))return false;if(f.ref&&!(p.allocations||[]).some(a=>a.ref===f.ref))return false;if(f.legacy&&!Object.keys(p.legacy||{}).length)return false;return hasQ("payments",p,f.q)});
 return sortRows(rows,f.sort,{date:p=>p.date||"",amount:p=>payGbp(p)},"date_desc")}
function payRow(p){const[ct,cc]=payCheck(p);const refs=(p.allocations||[]).map(a=>a.ref).filter(Boolean);const inn=p.direction==="in";
 return`<div class="row" role="button" tabindex="0" data-open="payments" data-id="${esc(p.no)}"><span class="ref">${rowCk("payments",p.no)}${esc(p.no)}<small>${esc(oldRefs(p))}</small></span>
 <span class="d"><b>${esc(pname(p.party))}${refs.length?" · "+esc(refs.join(", ")):""}</b><span>${fmtD(p.date)} · ${esc(L("payType",p.type)||"—")}${p.bank&&can("bank")?" · "+esc(bname(p.bank)):""}${p.platform?" · "+esc(L("platform",p.platform)):""}${p.company?" · "+esc(company(p.company)?.tag||cname(p.company)):""}${p.paidBy&&p.paidBy!=="company"?" · "+esc(L("paidBy",p.paidBy))+(p.person?" ("+esc(person(p.person)?.name||p.person)+")":""):""}${tagsTxt(p)}</span></span>
 <span class="amt num"><b>${inn?"+ ":""}${fmt(p.amount,p.cur)}</b><small class="cur">${p.cur!=="GBP"?gbp(payGbp(p)):inn?"money in":""}</small></span>
 <span class="amt num hm" title="${esc((p.allocations||[]).filter(a=>a.ref).map(a=>`${a.ref}: ${matchOf(a.ref,toGbp(a.amount,p.cur,p.date)||0,p.no).text}`).join(" · ")||"not applied to a reference")}"><b>${p.match!=null?Math.round(p.match*100)+"%":"—"}</b><small>match</small></span>
 <span class="stc">${pill(L("payType",p.type)||"—","p-info")}${ct==="Check match"?`<span class="pill ${cc}" title="${esc((p.allocations||[]).filter(a=>a.ref).map(a=>`${a.ref}: ${matchOf(a.ref,toGbp(a.amount,p.cur,p.date)||0,p.no).text}`).join(" · "))}">${esc(ct)} ⓘ</span>`:pill(ct,cc)}${p.status&&p.status!=="paid"?pill(L("payStatus",p.status),"p-mute"):""}</span></div>`}
function vPayments(v){const all=live(D.payments);const depts=[...new Set([...items("partyType",{all:true}).map(i=>i.dept),...all.map(payDept)].filter(Boolean))].map(d=>[d,deptLabel(d)]);const checks=[...new Set(all.map(p=>payCheck(p)[0]))].sort().map(c=>[c,c]);
 const controls=sel("payments","party","Party",partyOpts(null,all.map(p=>p.party)))+sel("payments","dept","Department",depts)+sel("payments","type","Type",listUnion("payType",all.map(p=>p.type)))+sel("payments","status","Status",listUnion("payStatus",all.map(p=>p.status)))+(can("bank")?sel("payments","bank","Bank",bankOpts(all.map(p=>p.bank))):"")+sel("payments","platform","Paid via",listUnion("platform",all.map(p=>p.platform)))+sel("payments","paidBy","Paid by",listUnion("paidBy",all.map(p=>p.paidBy)))+sel("payments","company","Company",compOpts(all.map(p=>p.company)))+sel("payments","cur","Currency",listUnion("currency",all.map(p=>p.cur)))+sel("payments","check","Check",checks)+sel("payments","tag","Tag",tagOpts())+amountInputs("payments");
 listPage(v,"payments",{title:"Payments",newKey:"payment",newLabel:"Payment",controls,years:yearsOf(all),sub:rows=>`${rows.length} payments · ${gbp(rows.filter(p=>p.status==="paid").reduce((s,p)=>s+payGbp(p)*paySign(p),0))} paid in this view`,
  sorts:[["date_desc","Newest"],["date_asc","Oldest"],["amount_desc","Amount high→low"],["amount_asc","Amount low→high"]],def:"date_desc",hidden:[["ref","For reference"],["legacy","Unmapped legacy values"]],head:[["","Ref"],["date","Payment"],["amount","Amount",1],["","Match",1],["","Check"]]})}

/* ===================== Stock ===================== */
function stockRows(){const f=F("stock");const warn=DEF().reorderWarnDays||30;const rows=stockProducts().filter(p=>{if(f.sku&&p.sku!==f.sku)return false;if(f.brand&&p.brand!==f.brand)return false;if(f.category&&!catMatch(p.category,f.category))return false;if(f.status&&(p.status||"active")!==f.status)return false;return hasQ("products",p,f.q)})
 .map(p=>({p,st:stockOf(p.sku),ro:reorderInfo(p.sku)})).filter(r=>{if(f.loc&&!(r.st.byLoc[f.loc]>0))return false;if(f.only&&!(r.st.onHand>0||r.st.transit>0||r.st.onOrder>0))return false;if(f.reorder&&!(r.ro.out||(r.ro.reorderIn!=null&&r.ro.reorderIn<=warn)))return false;return true});
 return sortRows(rows,f.sort,{value:r=>r.st.value,days:r=>r.ro.daysLeft==null?null:r.ro.daysLeft,name:r=>(r.p.name||"").toLowerCase(),onhand:r=>r.st.onHand},"value_desc")}
function stockRow(r){const{p,st,ro}=r;const warn=DEF().reorderWarnDays||30;const locsTxt=Object.entries(st.byLoc).filter(([,q])=>q>0).map(([l,q])=>`${esc(locName(l))} ${q}`).join(" · ");
 const dp=ro.out?pill("Out of stock","p-bad"):ro.daysLeft==null?pill("No sales yet","p-mute"):pill(`${Math.round(ro.daysLeft)} d left`,ro.reorderIn<=0?"p-bad":ro.reorderIn<=warn?"p-warn":"p-ok");
 return`<div class="row" role="button" tabindex="0" data-open="products" data-id="${esc(p.sku)}"><span class="ref">${esc(p.sku)}<small>pack of ${esc(p.packOf||1)}</small></span>
 <span class="d"><b>${esc(p.name)}</b><span>${locsTxt||"no stock in hand"}${st.transit?" · in transit "+st.transit:""}${st.onOrder?" · on order "+st.onOrder:""}${ro.velocity?" · sells "+(ro.velocity*7).toFixed(1)+"/wk":""}</span></span>
 <span class="amt num"><b>${st.onHand}</b><small>packs in hand${st.quarantine?` · ${st.quarantine} damaged`:""}</small></span>
 <span class="amt num hm"><b>${gbp(st.value)}</b><small>${st.avgCost?fmt(st.avgCost,"GBP")+" / pack":""}</small></span>
 <span class="stc">${dp}${st.alert?pill("⚠ batch cost gap","p-warn"):""}</span></div>`}
function vStock(v){const prods=stockProducts();const sts=prods.map(p=>stockOf(p.sku));const tot=sts.reduce((s,x)=>s+x.onHand,0),val=sts.reduce((s,x)=>s+x.value,0);const qq=sts.reduce((s,x)=>s+x.quarantine,0),qv=sts.reduce((s,x)=>s+x.quarantineValue,0);
 const controls=sel("stock","brand","Brand",listUnion("brand",prods.map(p=>p.brand)))+sel("stock","category","Category",listUnion("category",prods.map(p=>p.category),{two:true}))+sel("stock","status","Status",listUnion("productStatus",prods.map(p=>p.status)))+sel("stock","loc","Location",locOpts(sts.flatMap(x=>Object.keys(x.byLoc))))+tog("stock","reorder","Needs reorder")+tog("stock","only","Only with stock");
 const acts=can("create")?`<button class="btn" data-act="new" data-k="receive">Receive</button><button class="btn" data-act="new" data-k="move">Move</button><button class="btn" data-act="new" data-k="count">Stock count</button><button class="btn" data-act="scan">📷 Scan</button>`:"";
 listPage(v,"stock",{hidden:[["sku","One product"]],title:"Stock",sub:`${num(tot)} sellable packs in hand · ${gbp(val)} landed value${qq?` · ${num(qq)} damaged / quarantine (${gbp(qv)}) not included`:""} · built only from receipts and movements ${how(`Stock value = Σ over every product of (packs left in each open sellable batch × that batch's landed £/pack) = ${gbp2(val)}. Damaged / quarantine locations (Setup › Locations) are kept out${qq?`: ${num(qq)} packs, ${gbp2(qv)}`:""}. Each product's drawer shows its own sum.`)}`,controls,noDate:true,acts,sorts:[["value_desc","Value"],["onhand_desc","Packs in hand"],["days_asc","Days left"],["name_asc","Name"]],def:"value_desc",head:[["","SKU"],["name","Product"],["onhand","In hand",1],["value","Value",1],["days","Days left"]]})}

/* ===================== Products ===================== */
function productRows(){const f=F("products");const rows=D.products.filter(p=>!p.deletedAt&&!p.mergedInto).filter(p=>{if(f.brand&&p.brand!==f.brand)return false;if(f.category&&!catMatch(p.category,f.category))return false;if(f.status&&(p.status||"active")!==f.status)return false;if(f.supplier&&!(p.suppliers||[]).some(s=>s.party===f.supplier))return false;if(f.isnew==="new"&&!p.isNew)return false;if(f.isnew==="repeat"&&p.isNew)return false;if(f.noctn&&p.ctn?.L&&p.ctn?.W&&p.ctn?.H)return false;return hasQ("products",p,f.q)});
 return sortRows(rows,f.sort,{name:p=>(p.name||"").toLowerCase(),sku:p=>p.sku,price:p=>{const s=supOf(p);return s?toGbp(s.price,s.cur,today()):null}},"name_asc")}
