const partyBalance=code=>openPOs().filter(p=>p.party===code).reduce((s,p)=>s+poState(p).outstandingGbp,0);
function partyRows(){const f=F("parties");let rows=live(D.parties).filter(p=>{if(!f.archived&&p.status==="archived")return false;if(f.type&&p.type!==f.type)return false;if(f.country&&p.country!==f.country)return false;if(f.cur&&p.cur!==f.cur)return false;return hasQ("parties",p,f.q)}).map(p=>({p,bal:partyBalance(p.code)}));if(f.owing)rows=rows.filter(r=>r.bal>0.5);
 return sortRows(rows,f.sort,{name:r=>(r.p.name||"").toLowerCase(),balance:r=>r.bal,code:r=>r.p.code},"name_asc")}
