 const td=(x,n)=>`<td${n?' class="n"':""}>${x}</td>`;const tbl=(heads,rows,empty)=>rows.length?`<div class="tbl"><table><thead><tr>${heads.map(([h,r])=>`<th${r?' class="n"':""}>${esc(h)}</th>`).join("")}</tr></thead><tbody>${rows.join("")}</tbody></table></div>`:`<div class="empty">${esc(empty||"No data for this filter.")}</div>`;
