/* ===================== All alerts ===================== */
function attentionRows(){const f=F("attention");const any=f.s0||f.s1||f.s2||f.s3;return attn().filter(a=>(!any||f["s"+(a.sev|0)])&&(!f.col||(a.col||a.view)===f.col)&&(!f.q||score(a.text,f.q)>0))}
function vAttention(v){const f=F("attention");const all=attn();const{rows,html}=listBody("attention");const cols=[...new Set(all.map(a=>a.col||a.view).filter(Boolean))].map(c=>[c,c]);
 v.innerHTML=`${crumb([["Home","home"],["All alerts"]])}<div class="hdr"><div><h1>All alerts</h1><p class="sub">${rows.length} of ${all.length} · sorted by urgency, then date</p></div></div>
 <div class="filters" role="group" aria-label="Filters">${[3,2,1,0].map(s=>`<button type="button" class="chipb ${f["s"+s]?"on":""}" data-f-toggle="s${s}" aria-pressed="${!!f["s"+s]}"><span class="sdot" style="display:inline-block;background:${SEV[s][2]};margin-right:5px;vertical-align:middle"></span>${SEV[s][1]} (${all.filter(a=>(a.sev|0)===s).length})</button>`).join("")}${sel("attention","col","Type",cols)}<input data-f="q" type="search" placeholder="Filter alerts" aria-label="Filter alerts" value="${esc(f.q||"")}">${activeCount("attention")?'<button type="button" class="chipb" data-act="clearf">Clear all</button>':""}</div>
 <div class="card"><div id="listbody">${html}</div><div id="listfoot">${listFooter("attention",rows,all.length)}</div></div>`}

