/* ===================== Trash ===================== */
function vTrash(v){const f=F("trash");const days=DEF().trashDays||30;const T=today();const all=[];COLS.filter(c=>!["views","log"].includes(c)).forEach(c=>(D[c]||[]).filter(x=>x.deletedAt).forEach(x=>all.push({col:c,x})));
 const counts={};all.forEach(i=>counts[i.col]=(counts[i.col]||0)+1);const rows=all.filter(i=>!f.col||i.col===f.col).sort((a,b)=>(a.x.deletedAt||"")<(b.x.deletedAt||"")?1:-1);S.lastRows.trash=rows;const owner=S.role==="owner";
 v.innerHTML=`${crumb([["Home","home"],["Trash"]])}<div class="hdr"><div><h1>Trash</h1><p class="sub">Deleted items stay ${days} days, then are removed for good. Restore anything with one tap.</p></div></div>
 <div class="filters" role="group" aria-label="Collections"><button type="button" class="chipb ${!f.col?"on":""}" data-gof='${gof("trash",{col:""})}' aria-pressed="${!f.col}">All (${all.length})</button>${Object.entries(counts).map(([c,n])=>`<button type="button" class="chipb ${f.col===c?"on":""}" data-gof='${gof("trash",{col:c})}' aria-pressed="${f.col===c}">${esc(c)} (${n})</button>`).join("")}</div>
 <div class="card">${rows.length?rows.map(({col,x})=>{const id=x.no||x.code||x.sku||x.id;const left=Math.max(0,days-diffDays((x.deletedAt||"").slice(0,10)||T,T));const by=SET().users?.find(u=>u.uid===x.deletedBy)?.name||x.deletedBy;
  return`<div class="att"><span class="sdot" style="background:${left<=5?"var(--bad)":"var(--muted)"}"></span><div class="t"><b>${esc(label(col,x)||id)}</b><div>${esc(col)} · deleted ${fmtD((x.deletedAt||"").slice(0,10))}${by?" by "+esc(by):""} · <b>${left} day${left===1?"":"s"} left</b></div></div><button type="button" class="btn sm" data-act="preview" data-col="${esc(col)}" data-id="${esc(id)}">Preview</button><button type="button" class="btn sm pri" data-act="restore" data-col="${esc(col)}" data-id="${esc(id)}">Restore</button>${owner?`<button type="button" class="btn sm danger" data-act="purge" data-col="${esc(col)}" data-id="${esc(id)}">Delete now</button>`:""}</div>`}).join(""):'<div class="empty">Trash is empty.</div>'}</div>`}

